package com.water.backend.service;

import com.water.backend.dto.request.BillingCycleRequest; import com.water.backend.entity.Community; import com.water.backend.repository.*; import com.water.backend.service.impl.BillingCycleServiceImpl; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class BillingCycleServiceTest { @Mock BillingCycleRepository repo; @Mock CommunityRepository communityRepo; @Mock ResidentRepository residentRepo; @Mock InvoiceService invoiceService; @InjectMocks BillingCycleServiceImpl service; @Test void rejectsInvalidDateRange(){BillingCycleRequest r=BillingCycleRequest.builder().communityId(1L).startDate(LocalDate.of(2026,2,1)).endDate(LocalDate.of(2026,1,1)).build();assertThrows(IllegalArgumentException.class,()->service.createBillingCycle(r));} @Test void createsCycle(){Community c=Community.builder().id(1L).build(); when(communityRepo.findById(1L)).thenReturn(Optional.of(c)); when(repo.existsByCommunityAndStartDateAndEndDate(any(),any(),any())).thenReturn(false); when(repo.save(any())).thenAnswer(i->i.getArgument(0)); var r=service.createBillingCycle(BillingCycleRequest.builder().communityId(1L).startDate(LocalDate.of(2026,1,1)).endDate(LocalDate.of(2026,1,31)).build()); assertEquals(1L,r.getCommunityId());}}
